  const parsed = joinMatchOptionsSchema.safeParse(options);
  if (!parsed.success) throw new ServerError(JoinRefusal.NoSuchMatch, NO_SUCH_MATCH_MESSAGE);
  const [listing] = await matchMaker.query({ name: MATCH_ROOM, code: parsed.data.code });
